examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    MonarchButton({{trigger}}, variant: .primary) { step = 0 }
    MonarchStepper(steps, current: step)
    switch step {
    case 0:
        Text("Set up two-step verification")
            .monarchTextStyle(.title)
            .accessibilityAddTraits(.isHeader)
        Text("Scan this QR code with an authenticator app, such as 1Password, Google Authenticator or Microsoft Authenticator.")
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
        if let otpauth, let qr = qrCode(otpauth.absoluteString) {
            VStack(spacing: theme.spacing.space2) {
                MonarchCard {
                    qr.interpolation(.none)
                        .resizable()
                        .scaledToFit()
                        .frame(width: theme.spacing.space24 * 2)
                        .accessibilityLabel("QR code for your authenticator app")
                        .accessibilityAddTraits(.isImage)
                }
                .fixedSize()
                Text(verbatim: {{accountName}})
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .frame(maxWidth: .infinity)
        }
        Text("Can’t scan it? Enter this key in the app instead.")
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
        MonarchCopyField("Setup key", value: secret, isLabelHidden: true)
        HStack(spacing: theme.spacing.space2) {
            Spacer(minLength: 0)
            MonarchButton("Cancel", variant: .secondary) { step = 0 }
            MonarchButton("Next", variant: .primary) { step = 1 }
        }
    case 1:
        MonarchOtpPinInput("6-digit code", text: $code, error: codeError) { _ in verifyCode() }
        MonarchButton("Verify", variant: .primary, action: verifyCode)
    default:
        MonarchRecoveryCodes(codes, onAcknowledge: { step = 0 })
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@Environment(\.openURL) private var openURL
@State private var step = 0
@State private var code = ""
@State private var codeError: String?
private let secret = {{secret}}
private var otpauth: URL? { URL(string: "otpauth://totp/Example:" + {{accountName}} + "?secret=" + secret + "&issuer=Example") }
private let codes: [MonarchRecoveryCode] = [{{recoveryCodes.0}}, {{recoveryCodes.1}}, {{recoveryCodes.2}}, {{recoveryCodes.3}}, {{recoveryCodes.4}}, {{recoveryCodes.5}}]
private let steps = [
    MonarchStepperStep(id: "scan", label: "Connect your app"),
    MonarchStepperStep(id: "verify", label: "Enter a code"),
    MonarchStepperStep(id: "recovery", label: "Save recovery codes"),
]

private func qrCode(_ text: String) -> Image? {
    guard let filter = CIFilter(name: "CIQRCodeGenerator") else { return nil }
    filter.setValue(Data(text.utf8), forKey: "inputMessage")
    guard let output = filter.outputImage,
        let image = CIContext().createCGImage(output, from: output.extent)
    else { return nil }
    return Image(decorative: image, scale: 1)
}

private func verifyCode() {
    // The app checks the code with the server, then moves on or sets codeError.
    codeError = code.count == 6 ? nil : "Enter all 6 digits."
    if codeError == nil { step = 2 }
}

